'use strict';
(() => {
  const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[char]));
  function cardSvg({score,total,title,subtitle,siteName,accent='#237a57'}){
    const percent=Math.round(score/total*100);
    return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#0b3d2e"/><stop offset="1" stop-color="${esc(accent)}"/></linearGradient></defs><rect width="1200" height="630" rx="38" fill="url(#g)"/><circle cx="1055" cy="112" r="170" fill="#d6ff67" opacity=".16"/><circle cx="1090" cy="560" r="235" fill="#fff" opacity=".08"/><text x="74" y="94" fill="#d6ff67" font-family="Arial,sans-serif" font-size="34" font-weight="700">LearnWithUs</text><text x="74" y="188" fill="#fff" font-family="Arial,sans-serif" font-size="48" font-weight="700">${esc(title)}</text><text x="74" y="340" fill="#fff" font-family="Arial,sans-serif" font-size="122" font-weight="800">${score}/${total}</text><text x="420" y="334" fill="#d6ff67" font-family="Arial,sans-serif" font-size="54" font-weight="700">${percent}%</text><text x="74" y="430" fill="#e9f4ed" font-family="Arial,sans-serif" font-size="33">${esc(subtitle)}</text><text x="74" y="505" fill="#fff" font-family="Arial,sans-serif" font-size="29" font-weight="700">Share the challenge with a friend!</text><text x="74" y="558" fill="#d7e9dd" font-family="Arial,sans-serif" font-size="25">${esc(siteName)}</text></svg>`;
  }
  window.renderLearnWithUsScoreCard=({container,score,total,title,subtitle,filename='learnwithus-score-card.svg',url='quiz.html'})=>{
    const svg=cardSvg({score,total,title,subtitle,siteName:location.host}),src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
    container.innerHTML=`<div class="score-card-share"><img src="${src}" alt="LearnWithUs score card: ${esc(score)} out of ${esc(total)}"><div class="score-card-actions"><a class="secondary score-download" download="${esc(filename)}" href="${src}">Download score card</a><button class="secondary score-share" type="button">Share with a friend</button><a class="secondary" href="${esc(url)}">Challenge a friend</a></div><p class="score-share-status" role="status" aria-live="polite">Save the image or share the challenge link. Let’s see what your friends know!</p></div>`;
    const button=container.querySelector('.score-share'),status=container.querySelector('.score-share-status'),shareUrl=new URL(url,location.href).href;
    button.addEventListener('click',async()=>{try{if(navigator.share){await navigator.share({title:'Try my LearnWithUs challenge',text:`I scored ${score}/${total} on LearnWithUs. Can you beat my score?`,url:shareUrl});status.textContent='Shared! Thanks for inviting a friend to learn.';}else if(navigator.clipboard){await navigator.clipboard.writeText(shareUrl);status.textContent='Challenge link copied. Send it to a friend!';}else{status.textContent='Use “Challenge a friend” to open the quiz link, or download your score card.';}}catch(error){if(error?.name!=='AbortError')status.textContent='Sharing was not available. Download the card or open the challenge link instead.';}});
  };
})();
